import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { COMPRESSION_LEVEL, zip } from '../../../../../../../../../../subject_repositories/zip-a-folder/lib/ZipAFolder';

describe('ZipAFolder.zip', () => {
    it('stores entries without deflate compression when uncompressed compression is requested', async () => {
        const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'zip-a-folder-uncompressed-'));
        const srcDir = path.join(tmpDir, 'src');
        const zipFile = path.join(tmpDir, 'out.zip');

        try {
            fs.mkdirSync(srcDir, { recursive: true });
            fs.writeFileSync(path.join(srcDir, 'payload.txt'), 'payload that must be stored, not deflated');

            await zip(srcDir, zipFile, { compression: COMPRESSION_LEVEL.uncompressed });

            const archive = fs.readFileSync(zipFile);
            const localFileHeaderSignature = 0x04034b50;
            let compressionMethod: number | undefined;

            for (let offset = 0; offset + 30 <= archive.length; offset++) {
                if (archive.readUInt32LE(offset) !== localFileHeaderSignature) {
                    continue;
                }

                const method = archive.readUInt16LE(offset + 8);
                const nameLength = archive.readUInt16LE(offset + 26);
                const extraLength = archive.readUInt16LE(offset + 28);
                const nameStart = offset + 30;
                const nameEnd = nameStart + nameLength;

                if (nameEnd + extraLength > archive.length) {
                    continue;
                }

                const name = archive.subarray(nameStart, nameEnd).toString('utf8');
                if (name === 'payload.txt' || name.endsWith('/payload.txt') || name.endsWith('\\payload.txt')) {
                    compressionMethod = method;
                    break;
                }
            }

            expect(compressionMethod).toBe(0);
        } finally {
            fs.rmSync(tmpDir, { recursive: true, force: true });
        }
    });
});
